//! Freeze for the generated item-defaults table (`itemdata.rs`, S1-F-17).
//!
//! `crates/tr-app/src/itemdata.rs` is generated by `tools/GenItemData/gen.py`
//! from the decompiled `Item.cs`: the 6 196 `Item.SetDefaults` rows plus the
//! names, the `netDefaults` table, `OnCreated` and the `ItemVariants` tables.
//! Nothing regenerated or verified it, so a hand-edit or a lossy merge could
//! silently change item behaviour away from the C#.
//!
//! This test pins a fingerprint of every generated, non-comment line of the
//! file (all 6 196 rows, every field) and checks the table's shape. The other
//! half of the freeze is the generator round-trip — a fresh run must reproduce
//! the committed file — which is `tools/GenItemData/gen.py --check` (run by
//! `tools/GenItemData/test_gen.py::test_dw_1_5_committed_table_is_current`).
//! This test is the always-on `cargo test` gate for the same table.
//!
//! To re-pin after a legitimate regeneration: run
//! `python tools/GenItemData/gen.py`, then replace `DATA_FNV1A64` with the
//! value the failing assertion prints.

use std::path::PathBuf;

/// FNV-1a (64-bit) over the concatenated non-comment lines, joined by `\n`.
/// Re-pinned for S1-H-8 (the sort fields `melee/ranged/magic/…`/`dye`/`mount_type`
/// added to every generated row).
const DATA_FNV1A64: u64 = 0xfca8_1564_5287_670a;
/// `ItemID.Count` (`ItemID.cs:14861`) — the number of `ItemDef` rows.
const ROWS: usize = 6196;

#[test]
fn the_generated_item_table_is_frozen() {
    let manifest = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let path = manifest.join("src").join("itemdata.rs");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "{} could not be read ({e}) — itemdata.rs is part of the tree, so its \
             absence means a merge dropped it",
            path.display()
        )
    });

    let mut rows = 0usize;
    let mut kept: Vec<&str> = Vec::new();
    for line in text.lines() {
        let t = line.trim();
        if t.is_empty() || t.starts_with("//") {
            continue;
        }
        if t.starts_with("ItemDef {") {
            rows += 1;
        }
        kept.push(t);
    }
    let blob = kept.join("\n");

    assert_eq!(
        rows, ROWS,
        "the item table must carry {ROWS} `ItemDef` rows (`ItemID.Count`, \
         ItemID.cs:14861)"
    );
    assert!(
        text.contains("pub static ITEMS: [ItemDef; 6196] = ["),
        "the ITEMS array declaration is gone"
    );
    assert!(
        text.contains("pub static NAMES: [&str; 6196] = ["),
        "the NAMES array declaration is gone"
    );

    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for b in blob.as_bytes() {
        h ^= u64::from(*b);
        h = h.wrapping_mul(0x0000_0100_0000_01b3);
    }
    assert_eq!(
        h, DATA_FNV1A64,
        "the generated item table drifted from the pinned build (S1-F-17) — either \
         regenerate it with `python tools/GenItemData/gen.py` (then re-pin \
         DATA_FNV1A64) or restore the hand-edit"
    );
}
